(() => {
  function decodeEmail(encoded) {
    let email = '';
    const r = parseInt(encoded.substr(0, 2), 16);
    for (let n = 2; n < encoded.length; n += 2) {
      const charCode = parseInt(encoded.substr(n, 2), 16) ^ r;
      email += String.fromCharCode(charCode);
    }
    return decodeURIComponent(escape(email));
  }

  function run() {
    const elements = document.querySelectorAll('.__cf_email__');
    elements.forEach(el => {
      const encoded = el.getAttribute('data-cfemail');
      if (encoded) {
        try {
          const decoded = decodeEmail(encoded);
          const link = el.closest('a');
          if (link) {
            link.href = 'mailto:' + decoded;
          }
          el.parentNode.replaceChild(document.createTextNode(decoded), el);
        } catch (e) {}
      }
    });

    document.querySelectorAll('a[href^="/cdn-cgi/l/email-protection#"]').forEach(a => {
      const hash = a.href.split('#')[1];
      if (hash) {
        try {
          const decoded = decodeEmail(hash);
          a.href = 'mailto:' + decoded;
        } catch (e) {}
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', run);
  } else {
    run();
  }
})();
